//! Roc modules from schemas.
//!
//! Roc has no build scripts, so the modules are generated by `haus-gen roc`
//! and checked in, like protobuf output. Each schema becomes one module with
//! a type, a decoder and an encoder per named type:
//!
//! | haus                       | Roc                                           |
//! |----------------------------|-----------------------------------------------|
//! | `{ a: T, b?: U }`          | `{ a : T, b : [Missing, Present(U)] }`        |
//! | `< A \| B T \| C { … } >`  | `[A, B(T), C({ … }), Unknown(Str, List(Value))]` (open) |
//! | `Maybe a`, `Result e a`    | `[None, Some(a)]`, `Try(a, e)`                |
//! | `Array a`, `Map v`         | `List(a)`, `List((Str, v))`                   |
//! | `Int`, `Int8`…`UInt64`     | `Int` (any size, exact digits), `I8`…`U64`    |
//! | `Float32`, `Float64`       | `F32`, `F64`                                  |
//! | `Decimal`, std/time        | `Str` (exact text; std/time checked)          |
//! | `< >`                      | `[Bare(Str), Other(Str, List(Value))]`        |
//! | `Any`                      | `Value`                                       |
//! | `Secret a`                 | `Secret(a)` (`<redacted>` when inspected)     |
//! | `type Pair a = …`          | `Pair(a)`, with `decode_pair(v, decode_a)`    |
//!
//! Named variants are nominal (`:=`), so they can be recursive, and so are
//! records and other types that refer to themselves (`Tree := { children :
//! List(Tree) }`). A type named like a Roc builtin or an imported module
//! (`List`, `F64`, `Box`, `Value`) gets a `_` at the end in Roc (`List_`);
//! its functions keep their names (`decode_list`). A codec is a Roc module
//! with `Target`, `decode : Base -> Try(Target, Str)` and `encode : Target -> Base`.
//!
//! Roc has no deprecation marker: a `@deprecated` type, field or tag gets a
//! line in the type's doc comment (`## Deprecated field `mail`: use email.`).
//!
//! With [`RocConfig::json`] (`haus-gen roc --json`), each type also gets
//! `from_json_<name> : JsonValue -> Try(T, Decode.Error)` and
//! `to_json_<name> : T -> Try(JsonValue, Encode.Error)` for its schema-based JSON
//! (spec §16.3). `from_json_<name>` checks that the value it read nests at
//! most 256 levels as a haus value (§16, "Limits"); `read_json_<name>`
//! doesn't, and is what the readers of other types call. A generic type's
//! reader doesn't check either. Whether a `Maybe` writes `None` as `null` depends on whether
//! its inner type's JSON can be `null`; Roc has no traits, so that is decided
//! here, and a generic type takes a `Bool` for each parameter
//! (`from_json_pair(j, from_json_a, nullable_a)`). The schema packages a
//! module imports must be generated with JSON too.

//!
//! A schema's imports are loaded and checked by haus-fmt-schema (spec
//! §13.3). Schema packages are given explicitly ([`RocConfig::package`],
//! `haus-gen roc --package DIR=ALIAS`): each is a Roc package of its own
//! (generated with `haus-gen roc-package`), imported under its alias. The
//! application's files a schema imports (`import ./common (Address)`) each
//! get a module of their own, named after the root module and their path
//! from its directory: `OrderCommon`, `OrderBillingCommon` for
//! `billing/common.schema.haus`, `OrderUpSharedMoney` for
//! `../shared/money.schema.haus`; their ids are their paths from there
//! (`billing/common#Address`).

use crate::codegen::unknown_type;
use crate::graph::{self, Origin, Unit};
use crate::schema::{self, Attribute, Case, Field, Ty, TypeDef, deprecation, error};
use crate::{Error, Result};
use haus::ErrorCode as Code;
use haus_schema::packages::MANIFEST;
use haus_schema::{Explicit, InstanceId, Manifest, Options as LoadOptions, Packages, Schema, Type};
use std::collections::{HashMap, HashSet};
use std::fmt::Write as _;
use std::fs;
use std::path::{Path, PathBuf};

/// How to generate a Roc module.
#[derive(Debug, Clone, Default)]
pub struct RocConfig {
    /// Codecs: a type's id, and the Roc module of its codec.
    codecs: Vec<(String, String)>,
    /// Schema packages: their directory, and the alias the app gives their Roc package.
    packages: Vec<(PathBuf, String)>,
    /// Folders of schema packages.
    folders: Vec<PathBuf>,
    without_attributes: bool,
    json: bool,
}

impl RocConfig {
    pub fn new() -> RocConfig {
        RocConfig::default()
    }

    /// Use the codec module `module` for the type with this id.
    pub fn codec(mut self, id: impl Into<String>, module: impl Into<String>) -> RocConfig {
        self.codecs.push((id.into(), module.into()));
        self
    }

    /// The schema package in `dir`, imported in Roc under `alias` (`money: "…/main.roc"`).
    pub fn package(mut self, dir: impl Into<PathBuf>, alias: impl Into<String>) -> RocConfig {
        self.packages.push((dir.into(), alias.into()));
        self
    }

    /// The schema packages in `folder`: its subdirectories with a
    /// `package.haus`. Each is imported in Roc under the last part of its
    /// name, in snake case (`money` for `@haus-fmt/money`), unless
    /// [`RocConfig::package`] gives it another alias.
    pub fn folder(mut self, folder: impl Into<PathBuf>) -> RocConfig {
        self.folders.push(folder.into());
        self
    }

    /// Leave the schema's attributes out, as if they weren't written: the
    /// module decodes and encodes the same (spec §15). For tests of that.
    #[doc(hidden)]
    pub fn without_attributes(mut self) -> RocConfig {
        self.without_attributes = true;
        self
    }

    /// Also generate `from_json_<name>` and `to_json_<name>` for the schema-based
    /// JSON of each type (spec §16.3), with the haus modules `JsonValue`,
    /// `FromJson` and `ToJson`.
    pub fn json(mut self) -> RocConfig {
        self.json = true;
        self
    }

    /// The modules for an application's schema file, with id `id`: its own,
    /// named `module`, then one for each file it imports, directly or not
    /// (`OrderCommon`), as (name, code).
    pub fn modules(&self, schema: &Path, module: &str, id: &str) -> Result<Vec<(String, String)>> {
        let packages = self.packages.iter().map(|(dir, alias)| (dir.as_path(), alias.as_str()));
        let given = Given::new(packages, &self.folders)?;
        let options = LoadOptions {
            packages: &given.explicit,
            id: Some(id),
            without_attributes: self.without_attributes,
            ..LoadOptions::default()
        };
        let loaded = Schema::load_with(schema, &options)?;
        let units = graph::units(&loaded, self.without_attributes)?;
        generate_units(&loaded, &units, module, &given, &self.codecs, self.json)
    }

    /// The module for an application's schema file, named `module`, with id
    /// `id`. A schema that imports other files of the application needs
    /// their modules too: [`RocConfig::modules`].
    pub fn generate(&self, schema: &Path, module: &str, id: &str) -> Result<String> {
        let mut modules = self.modules(schema, module, id)?;
        match modules.len() {
            1 => Ok(modules.remove(0).1),
            _ => Err(Error::at(
                schema,
                Code::ImportUnavailable,
                "the schema imports other files, which get modules of their own: generate them all \
                 (haus-gen roc with --out writes them next to it)",
            )),
        }
    }

    /// The module of the schema package in `dir`: its name and ids come from the manifest.
    pub fn generate_package(&self, dir: &Path) -> Result<(String, String)> {
        let manifest = Manifest::read(dir)?;
        let module = package_module(&manifest.name);
        let schema = manifest.schema_path(dir)?;
        let code = self.generate(&schema, &module, &manifest.id())?;
        Ok((module, code))
    }

    /// Write [`RocConfig::generate`]'s module to `out`.
    pub fn write(&self, schema: &Path, module: &str, id: &str, out: &Path) -> Result<()> {
        let code = self.generate(schema, module, id)?;
        fs::write(out, code).map_err(|e| Error::at(out, Code::ImportNotFound, e))
    }
}

/// The packages given: where they are, and the alias of each one's Roc package, by name.
#[derive(Default)]
struct Given {
    explicit: Explicit,
    aliases: HashMap<String, String>,
}

impl Given {
    fn new<'a>(packages: impl IntoIterator<Item = (&'a Path, &'a str)>, folders: &[PathBuf]) -> Result<Given> {
        let given = packages.into_iter().try_fold(Given::default(), |g, (dir, alias)| {
            let mut aliases = g.aliases;
            aliases.entry(Manifest::read(dir)?.name).or_insert_with(|| alias.to_owned());
            Ok::<_, Error>(Given { explicit: g.explicit.package(dir)?, aliases })
        })?;
        folders.iter().try_fold(given, |g, folder| {
            let explicit = g.explicit.folder(folder)?;
            let mut aliases = g.aliases;
            let entries = fs::read_dir(folder).map_err(|e| Error::at(folder, Code::ImportNotFound, e))?;
            // A subdirectory whose manifest is invalid is left out, as the explicit packages leave it out.
            let dirs =
                entries.filter_map(|e| Some(e.ok()?.path())).filter(|d| d.join(MANIFEST).symlink_metadata().is_ok());
            for name in dirs.filter_map(|dir| Manifest::read(&dir).ok()).map(|m| m.name) {
                let alias = name.rsplit('/').next().map(snake).unwrap_or_default();
                aliases.entry(name).or_insert(alias);
            }
            Ok(Given { explicit, aliases })
        })
    }

    /// `money.HausFmtMoney`: the Roc module with a package's types.
    fn module(&self, package: &str) -> String {
        let alias = self.aliases.get(package).map_or("", String::as_str);
        format!("{alias}.{}", package_module(package))
    }
}

/// `@haus-fmt/money` → `HausFmtMoney`: the organisation too, so the module's name
/// never clashes with a type in it (`HausFmtMoney.Money`).
fn package_module(name: &str) -> String {
    pascal(name)
}

/// The Roc module for a schema given as text (it imports std modules and
/// `packages`, each package's crate name being its Roc alias, not files).
pub fn generate(
    text: &str,
    module: &str,
    id: &str,
    codecs: &[(String, String)],
    packages: &Packages,
) -> Result<String> {
    generate_text(text, module, id, codecs, packages, false)
}

/// [`generate`], with `from_json_<name>` and `to_json_<name>` for each type (see [`RocConfig::json`]).
pub fn generate_with_json(
    text: &str,
    module: &str,
    id: &str,
    codecs: &[(String, String)],
    packages: &Packages,
) -> Result<String> {
    generate_text(text, module, id, codecs, packages, true)
}

fn generate_text(
    text: &str,
    module: &str,
    id: &str,
    codecs: &[(String, String)],
    packages: &Packages,
    json: bool,
) -> Result<String> {
    let given = Given::new(packages.iter().map(|p| (p.dir.as_path(), p.krate.as_str())), &[])?;
    let options = LoadOptions { packages: &given.explicit, id: Some(id), ..LoadOptions::default() };
    let loaded = Schema::parse_with(text, &options)?;
    let units = graph::units(&loaded, false)?;
    let mut modules = generate_units(&loaded, &units, module, &given, codecs, json)?;
    Ok(modules.remove(0).1)
}

/// The modules of a schema's files: the root's, named `module`, then one for each file it imports.
fn generate_units(
    schema: &Schema,
    units: &[Unit],
    module: &str,
    given: &Given,
    codecs: &[(String, String)],
    json: bool,
) -> Result<Vec<(String, String)>> {
    let in_root = |e: Error| match units[0].path.as_deref() {
        Some(path) if e.path().is_none() => e.in_file(path),
        _ => e,
    };
    let owner = |package: &str| format!("the Roc module {}", given.module(package));
    graph::check_codecs(schema, units, codecs.iter().map(|(id, _)| id.as_str()), owner, "other packages' modules")
        .map_err(in_root)?;
    let names: Vec<String> = std::iter::once(module.to_owned())
        .chain(graph::module_names(&units[1..], &[module], "", |segments| {
            format!("{module}{}", segments.iter().map(|s| pascal(s)).collect::<String>())
        }))
        .collect();
    // The Roc modules each unit imports: packages' and other files' (codecs' come later).
    let roc_imports: Vec<Vec<String>> = units
        .iter()
        .map(|unit| {
            // In the order of the schema's imports.
            let origins = unit.file.imports.iter().filter_map(|imp| unit.imports.get(&imp.names.first()?.0));
            origins.fold(vec![], |mut imports: Vec<String>, origin| {
                let module = match origin {
                    Origin::Time => return imports,
                    Origin::Package { package, .. } => given.module(package),
                    Origin::File { unit, .. } => names[*unit].clone(),
                };
                if !imports.contains(&module) {
                    imports.push(module);
                }
                imports
            })
        })
        .collect();
    let roc_names: Vec<HashMap<String, String>> =
        units.iter().enumerate().map(|(u, unit)| roc_names(&unit.file, &names[u], &roc_imports[u], json)).collect();
    units
        .iter()
        .enumerate()
        .map(|(u, unit)| {
            let imports = unit
                .imports
                .iter()
                .map(|(name, origin)| {
                    let source = match origin {
                        Origin::Time => Source::Time,
                        Origin::Package { package, id, template, .. } => Source::Module {
                            module: package_module(package),
                            roc: name.clone(),
                            id: id.clone(),
                            template: *template,
                        },
                        Origin::File { unit: to, id, template, .. } => Source::Module {
                            module: names[*to].clone(),
                            roc: roc_names[*to].get(name).cloned().unwrap_or_else(|| name.clone()),
                            id: id.clone(),
                            template: *template,
                        },
                    };
                    (name.clone(), source)
                })
                .collect();
            let input = Input {
                schema,
                text: &unit.text,
                id: &unit.id,
                module: &names[u],
                imports,
                roc_imports: &roc_imports[u],
                roc_names: roc_names[u].clone(),
                codecs,
                json,
            };
            let code = generate_file(&unit.file, input).map_err(|e| match &unit.path {
                Some(path) if e.path().is_none() => e.in_file(path),
                _ => e,
            })?;
            Ok((names[u].clone(), code))
        })
        .collect()
}

/// What a module is generated from.
struct Input<'a> {
    schema: &'a Schema,
    text: &'a str,
    id: &'a str,
    module: &'a str,
    /// Where each imported type comes from.
    imports: HashMap<String, Source>,
    /// The Roc modules of packages and other files it imports.
    roc_imports: &'a [String],
    /// Each type's name in Roc.
    roc_names: HashMap<String, String>,
    codecs: &'a [(String, String)],
    json: bool,
}

/// Each type's name in Roc: a type named like a Roc builtin, a haus module,
/// an imported module or the module itself gets a `_` (`List_`).
fn roc_names(file: &schema::File, module: &str, roc_imports: &[String], json: bool) -> HashMap<String, String> {
    let taken: HashSet<&str> = BUILTIN_TYPES
        .iter()
        .chain(HAUS_MODULES)
        .chain(if json { JSON_MODULES } else { &[] })
        .copied()
        .chain(["Int", module])
        .chain(roc_imports.iter().map(|i| i.rsplit('.').next().unwrap_or(i)))
        .collect();
    let schema_names: HashSet<&str> = file.types.iter().map(|d| d.name.as_str()).collect();
    file.types
        .iter()
        .map(|d| {
            let mut name = d.name.clone();
            while taken.contains(name.as_str()) || (name != d.name && schema_names.contains(name.as_str())) {
                name.push('_');
            }
            (d.name.clone(), name)
        })
        .collect()
}

fn generate_file(file: &schema::File, input: Input) -> Result<String> {
    let Input { schema, text, id, module, imports, roc_imports, roc_names, codecs, json } = input;
    // The ids of the types this module has: its own, and those it imports.
    let ids: HashSet<String> = file
        .types
        .iter()
        .map(|d| format!("{id}#{}", d.name))
        .chain(imports.iter().map(|(n, source)| match source {
            Source::Module { id, .. } => id.clone(),
            Source::Time => format!("std/time#{n}"),
        }))
        .collect();
    // The codecs of its types.
    let codecs: Vec<&(String, String)> = codecs.iter().filter(|(cid, _)| ids.contains(cid)).collect();

    let defs: HashMap<&str, &TypeDef> = file.types.iter().map(|d| (d.name.as_str(), d)).collect();
    let recursive = file.types.iter().filter(|d| refers_to_itself(d, &defs)).map(|d| d.name.clone()).collect();
    let tagged_maybes = crate::codegen::tagged_maybes(&defs);

    let mut g = Gen {
        schema,
        text,
        id,
        defs,
        imports,
        codecs: codecs.iter().map(|(i, m)| (i.clone(), m.clone())).collect(),
        fresh: 0,
        fresh_json: 0,
        helpers: Vec::new(),
        names: file.types.iter().map(|d| d.name.clone()).collect(),
        uses_int: false,
        uses_secret: false,
        roc_names,
        recursive,
        params: Vec::new(),
        json,
        tagged_maybes,
        nullables_used: HashSet::new(),
    };
    let items = file.types.iter().map(|d| g.define(d)).collect::<Result<Vec<_>>>()?;
    let haus = HAUS_MODULES
        .iter()
        .chain(if json { JSON_MODULES } else { &[] })
        .copied()
        .chain(g.uses_int.then_some("Int"))
        .chain(g.uses_secret.then_some("Secret"))
        .map(|m| format!("haus.{m}"));
    // The modules of the codecs it uses.
    let used = |m: &str| items.iter().chain(&g.helpers).any(|i| i.contains(&format!("{m}.")));
    let mut roc_imports = roc_imports.to_vec();
    for (_, m) in codecs.iter().filter(|(_, m)| used(m)) {
        if !roc_imports.contains(m) {
            roc_imports.push(m.clone());
        }
    }
    let mut out = format!("## Generated by haus-gen from {id}. Don't edit.\n");
    for i in haus.chain(roc_imports) {
        let _ = writeln!(out, "import {i}");
    }
    let _ = write!(out, "\n{module} := [].{{\n");
    for item in items.iter().chain(&g.helpers) {
        let _ = writeln!(out, "{item}");
    }
    out.push_str("}\n");
    Ok(out)
}

/// The haus modules every generated module imports.
const HAUS_MODULES: &[&str] = &["Value", "Decode", "Encode"];

/// The haus modules a module with JSON imports too.
const JSON_MODULES: &[&str] = &["JsonValue", "FromJson", "ToJson"];

/// Where an imported type comes from.
enum Source {
    Time,
    /// Another module: a package's (`HausFmtMoney`) or another file's
    /// (`OrderCommon`), with the type's name there, its id, and its template.
    Module {
        module: String,
        roc: String,
        id: String,
        template: InstanceId,
    },
}

/// Decoding or encoding `x`: a function's name, or an expression with `{x}`.
#[derive(Clone)]
enum F {
    Name(String),
    Template(String),
}

impl F {
    /// Applied to the expression `arg`: `f(arg)`.
    fn apply(&self, arg: &str) -> String {
        match self {
            F::Name(f) => format!("{f}({arg})"),
            F::Template(t) => t.replace("{x}", arg),
        }
    }
}

/// A Roc type, its decoder and encoder, its schema-based JSON reader and writer,
/// and whether its JSON can be `null`.
struct R {
    ty: String,
    de: F,
    en: F,
    from_json: F,
    to_json: F,
    nullable: Nullable,
}

impl R {
    /// A type whose functions have these names.
    fn named(ty: &str, de: &str, en: &str, from_json: &str, to_json: &str) -> R {
        R::new(ty, F::Name(de.into()), F::Name(en.into()), F::Name(from_json.into()), F::Name(to_json.into()))
    }

    fn new(ty: &str, de: F, en: F, from_json: F, to_json: F) -> R {
        R { ty: ty.into(), de, en, from_json, to_json, nullable: Nullable::Never }
    }

    /// A prelude type with the functions `Decode.<f>`, `Encode.<f>`, `FromJson.<f>` and `ToJson.<f>`.
    fn prelude(ty: &str, f: &str) -> R {
        R::named(ty, &format!("Decode.{f}"), &format!("Encode.{f}"), &format!("FromJson.{f}"), &format!("ToJson.{f}"))
    }
}

/// Whether a type's JSON can be `null` (spec §16.3): never, always (a
/// `Maybe` that writes `None` as `null`), or as a type parameter's can be
/// (`nullable_a`), or can't (`!nullable_a`).
#[derive(Clone, PartialEq)]
enum Nullable {
    Never,
    Always,
    Param { name: String, negated: bool },
}

impl Nullable {
    fn not(self) -> Nullable {
        match self {
            Nullable::Never => Nullable::Always,
            Nullable::Always => Nullable::Never,
            Nullable::Param { name, negated } => Nullable::Param { name, negated: !negated },
        }
    }
}

struct Gen<'a> {
    schema: &'a Schema,
    text: &'a str,
    id: &'a str,
    defs: HashMap<&'a str, &'a TypeDef>,
    imports: HashMap<String, Source>,
    codecs: HashMap<String, String>,
    /// For fresh lambda parameters (Roc doesn't allow shadowing): `x1` in
    /// decoders and encoders, `y1` in JSON readers and writers.
    fresh: usize,
    fresh_json: usize,
    /// Decoders and encoders of inline types.
    helpers: Vec<String>,
    names: HashSet<String>,
    /// Whether the module needs `haus.Int`.
    uses_int: bool,
    /// Whether the module needs `haus.Secret`.
    uses_secret: bool,
    /// Each schema type's name in Roc (`List` → `List_`).
    roc_names: HashMap<String, String>,
    /// Types that refer to themselves, so they are nominal in Roc.
    recursive: HashSet<String>,
    /// The parameters of the definition being generated, and their names in Roc.
    params: Vec<(String, String)>,
    /// Whether to generate `from_json_<name>` and `to_json_<name>`.
    json: bool,
    /// The `Maybe`s that always use the tagged form in JSON, by position.
    tagged_maybes: HashSet<usize>,
    /// The parameters whose `nullable_<p>` the function being generated uses.
    nullables_used: HashSet<String>,
}

impl Gen<'_> {
    fn fail<T>(&self, pos: usize, code: Code, reason: impl Into<String>) -> Result<T> {
        Err(error(self.text, pos, code, reason).into())
    }

    /// A type parameter in Roc: `a`, and its decoder `decode_a`, which must
    /// not be the decoder of a type (`type A`, `type Box a`): then `a_`.
    fn param_name(&self, param: &str) -> String {
        let mut name = field_name(param);
        while self.defs.keys().any(|d| snake(d) == name) {
            name.push('_');
        }
        name
    }

    /// Whether the JSON of `ty` can be `null`, with the current definition's
    /// parameters as `nullable_<p>`. Only `Maybe` makes it so; one that
    /// reaches itself always uses the tagged form.
    fn nullable_of(&self, ty: &Ty, env: &HashMap<String, Nullable>, seen: &mut HashSet<String>) -> Nullable {
        match ty {
            Ty::Param { name, .. } => env.get(name).cloned().unwrap_or(Nullable::Never),
            Ty::Record { .. } | Ty::Variant { .. } => Nullable::Never,
            Ty::Name { name, args, pos } => match (name.as_str(), args.as_slice()) {
                ("Maybe", [inner]) if !self.tagged_maybes.contains(pos) => self.nullable_of(inner, env, seen).not(),
                ("Secret", [inner]) => self.nullable_of(inner, env, seen),
                (name, args) => match self.defs.get(name) {
                    None => match self.imports.get(name) {
                        // A type of another module: from its resolved type.
                        Some(Source::Module { template, .. }) => {
                            let instance = self.schema.instance(*template);
                            let inner = instance
                                .args
                                .iter()
                                .zip(args)
                                .filter_map(|(p, a)| match p {
                                    Type::Param(p) => Some((p.clone(), self.nullable_of(a, env, seen))),
                                    _ => None,
                                })
                                .collect();
                            nullable_resolved(self.schema, &instance.body, &inner, &mut HashSet::new())
                        }
                        _ => Nullable::Never,
                    },
                    Some(def) if seen.insert(name.to_owned()) => {
                        let inner = def
                            .params
                            .iter()
                            .zip(args)
                            .map(|(p, a)| (p.clone(), self.nullable_of(a, env, seen)))
                            .collect();
                        let n = self.nullable_of(&def.ty, &inner, seen);
                        seen.remove(name);
                        n
                    }
                    _ => Nullable::Never,
                },
            },
        }
    }

    /// `nullable` as Roc code, noting the parameters it uses.
    fn nullable_code(&mut self, nullable: &Nullable) -> String {
        match nullable {
            Nullable::Never => "False".into(),
            Nullable::Always => "True".into(),
            Nullable::Param { name, negated } => {
                self.nullables_used.insert(name.clone());
                format!("{}nullable_{name}", if *negated { "!" } else { "" })
            }
        }
    }

    /// The JSON arguments for parameters passed on: `, from_json_a, nullable_a`
    /// and `, to_json_a, nullable_a`.
    fn json_args(&mut self, params: &[String]) -> (String, String) {
        params.iter().fold((String::new(), String::new()), |(mut from, mut to), p| {
            self.nullables_used.insert(p.clone());
            let _ = write!(from, ", from_json_{p}, nullable_{p}");
            let _ = write!(to, ", to_json_{p}, nullable_{p}");
            (from, to)
        })
    }

    /// `f`, a JSON reader or writer, as a function value.
    fn json_value(&mut self, f: &F) -> String {
        match f {
            F::Name(n) => n.clone(),
            F::Template(t) => {
                self.fresh_json += 1;
                let y = format!("y{}", self.fresh_json);
                format!("|{y}| {}", t.replace("{x}", &y))
            }
        }
    }

    /// `f` as a function value.
    fn value(&mut self, f: &F) -> String {
        match f {
            F::Name(n) => n.clone(),
            F::Template(t) => {
                self.fresh += 1;
                let x = format!("x{}", self.fresh);
                format!("|{x}| {}", t.replace("{x}", &x))
            }
        }
    }

    /// The type, decoder and encoder of a definition.
    fn define(&mut self, def: &TypeDef) -> Result<String> {
        self.params = def.params.iter().map(|p| (p.clone(), self.param_name(p))).collect();
        self.nullables_used.clear();
        let deprecations = deprecations(def);
        let doc: String = def
            .doc
            .lines()
            .chain(["", &format!("haus type `{}#{}`.", self.id, def.name)])
            // A message may have line breaks; each line needs its `##`.
            .chain(deprecations.iter().flat_map(|d| d.split('\n')))
            .skip_while(|l| l.is_empty())
            .fold(String::new(), |mut out, l| {
                let _ = writeln!(out, "\t##{}{l}", if l.is_empty() { "" } else { " " });
                out
            });
        if let Ty::Name { name, args, .. } = &def.ty
            && name == "Stream"
        {
            let item = match args.as_slice() {
                [Ty::Name { name, .. }, ..] => name.as_str(),
                _ => "",
            };
            return Ok(format!("{doc}\t# A stream of {item}: read it with Streaming and decode_{}.\n", snake(item)));
        }
        let snake_name = snake(&def.name);
        // `Pair(a)`; records and other types that refer to themselves are nominal.
        let head = match self.params.as_slice() {
            [] => self.roc_names[&def.name].clone(),
            ps => format!(
                "{}({})",
                self.roc_names[&def.name],
                ps.iter().map(|(_, p)| p.as_str()).collect::<Vec<_>>().join(", ")
            ),
        };
        let is = if self.recursive.contains(&def.name) { ":=" } else { ":" };
        let (decl, body) = match &def.ty {
            Ty::Record { closed, fields, .. } => {
                let (ty, body) = self.record(&def.name, *closed, fields)?;
                (format!("{head} {is} {ty}"), body)
            }
            Ty::Variant { closed: false, cases, .. } if cases.is_empty() => {
                let r = any_tag();
                (format!("{head} : {}", r.ty), Bodies::of(&r))
            }
            Ty::Variant { closed, cases, .. } => {
                let (ty, body) = self.variant(&def.name, *closed, cases)?;
                (format!("{head} := {ty}"), body)
            }
            ty if self.recursive.contains(&def.name) => {
                // Roc allows recursion only through a tag or a record field:
                // `type Nested = Array Nested` is `Nested := [Nested(List(Nested))]`.
                let r = self.lower(ty, &def.name)?;
                let tag = &def.name;
                let unwrap = |f: &F| format!("match v {{\n\t\t{tag}(x) => {}\n\t}}", f.apply("x"));
                let body = Bodies {
                    de: format!("Ok({tag}({}?))", r.de.apply("v")),
                    en: unwrap(&r.en),
                    from_json: format!("Ok({tag}({}?))", r.from_json.apply("j")),
                    to_json: unwrap(&r.to_json),
                };
                (format!("{head} := [{tag}({})]", r.ty), body)
            }
            ty => {
                let r = self.lower(ty, &def.name)?;
                (format!("{head} : {}", r.ty), Bodies::of(&r))
            }
        };
        // A decoder and an encoder for each parameter; `_` for those the type doesn't use.
        let used = params_in(&def.ty);
        let p = Params::new(
            self.params.iter().map(|(h, p)| (p.clone(), used.contains(h), self.nullables_used.contains(p))),
        );
        let params_given = !self.params.is_empty();
        self.params.clear();
        let v = encoded_var(&def.ty);
        let json = match (self.json, params_given) {
            (false, _) => Json::None,
            (true, true) => Json::Unchecked,
            (true, false) => Json::Checked,
        };
        Ok(functions(&doc, &decl, &snake_name, &head, &body, &p, v, json))
    }

    /// A Roc type for a type expression; `hint` names inline types.
    fn lower(&mut self, ty: &Ty, hint: &str) -> Result<R> {
        let r = match ty {
            Ty::Param { name, pos } => match self.params.iter().find(|(h, _)| h == name) {
                Some((_, p)) => R::named(
                    p,
                    &format!("decode_{p}"),
                    &format!("encode_{p}"),
                    &format!("from_json_{p}"),
                    &format!("to_json_{p}"),
                ),
                None => return self.fail(*pos, Code::UnknownParameter, format!("unknown type parameter {name}")),
            },
            Ty::Record { .. } | Ty::Variant { .. } => self.inline(ty, hint)?,
            Ty::Name { name, args, pos } => self.named(name, args, *pos, hint)?,
        };
        let env =
            self.params.iter().map(|(h, p)| (h.clone(), Nullable::Param { name: p.clone(), negated: false })).collect();
        Ok(R { nullable: self.nullable_of(ty, &env, &mut HashSet::new()), ..r })
    }

    fn named(&mut self, name: &str, args: &[Ty], pos: usize, hint: &str) -> Result<R> {
        let arity = |n: usize| (args.len() != n).then(|| format!("{name} takes {n} argument(s), found {}", args.len()));
        // A type of this module, or of another one: its id, the module's prefix
        // (`OrderCommon.`), its Roc type, and its number of parameters.
        let named = match (self.defs.get(name), self.imports.get(name)) {
            (Some(def), _) => {
                Some((format!("{}#{name}", self.id), String::new(), self.roc_names[name].clone(), def.params.len()))
            }
            (None, Some(Source::Module { module, roc, id, template })) => {
                let params = self.schema.instance(*template).args.len();
                Some((id.clone(), format!("{module}."), format!("{module}.{roc}"), params))
            }
            _ => None,
        };
        let (id, base) = if let Some((id, prefix, roc, params)) = named {
            let s = snake(name);
            if params == 0 {
                // Its reader without the depth check (see `functions`).
                let r = R::named(
                    &roc,
                    &format!("{prefix}decode_{s}"),
                    &format!("{prefix}encode_{s}"),
                    &format!("{prefix}read_json_{s}"),
                    &format!("{prefix}to_json_{s}"),
                );
                (id, r)
            } else {
                // A generic type, applied: `Pair Int` is `Pair(Int)`, decoded with `decode_pair(v, Decode.int)`.
                if let Some(reason) = arity(params) {
                    return self.fail(pos, Code::WrongArity, reason);
                }
                if self.codecs.contains_key(&id) {
                    return self.fail(
                        pos,
                        Code::WrongArity,
                        format!("a codec for the generic type {name} is not supported in Roc"),
                    );
                }
                let rs = args
                    .iter()
                    .enumerate()
                    .map(|(i, a)| self.lower(a, &format!("{hint}{}", i + 1)))
                    .collect::<Result<Vec<_>>>()?;
                let ty = format!("{roc}({})", rs.iter().map(|r| r.ty.as_str()).collect::<Vec<_>>().join(", "));
                let (de, en): (Vec<_>, Vec<_>) = rs.iter().map(|r| (self.value(&r.de), self.value(&r.en))).unzip();
                let (from, to): (Vec<_>, Vec<_>) = rs
                    .iter()
                    .map(|r| {
                        let null = self.nullable_code(&r.nullable);
                        (
                            format!("{}, {null}", self.json_value(&r.from_json)),
                            format!("{}, {null}", self.json_value(&r.to_json)),
                        )
                    })
                    .unzip();
                return Ok(R::new(
                    &ty,
                    F::Template(format!("{prefix}decode_{s}({{x}}, {})", de.join(", "))),
                    F::Template(format!("{prefix}encode_{s}({{x}}, {})", en.join(", "))),
                    F::Template(format!("{prefix}from_json_{s}({{x}}, {})", from.join(", "))),
                    F::Template(format!("{prefix}to_json_{s}({{x}}, {})", to.join(", "))),
                ));
            }
        } else if let Some(Source::Time) = self.imports.get(name) {
            (
                format!("std/time#{name}"),
                R::named(
                    "Str",
                    &format!("Decode.time(\"{name}\")"),
                    &format!("Encode.time(\"{name}\")"),
                    &format!("FromJson.time(\"{name}\")"),
                    "ToJson.time",
                ),
            )
        } else {
            return self.prelude(name, args, pos, hint);
        };
        if let Some(reason) = arity(0) {
            return self.fail(pos, Code::WrongArity, reason);
        }
        Ok(match self.codecs.get(&id).cloned() {
            None => base,
            Some(codec) => {
                let (de, from) = (self.value(&base.de), self.json_value(&base.from_json));
                R::new(
                    &format!("{codec}.Target"),
                    F::Template(format!("Decode.codec({{x}}, {de}, {codec}.decode)")),
                    F::Template(base.en.apply(&format!("{codec}.encode({{x}})"))),
                    F::Template(format!("FromJson.codec({{x}}, {from}, {codec}.decode)")),
                    F::Template(base.to_json.apply(&format!("{codec}.encode({{x}})"))),
                )
            }
        })
    }

    fn prelude(&mut self, name: &str, args: &[Ty], pos: usize, hint: &str) -> Result<R> {
        let Some(&(_, params)) = schema::PRELUDE.iter().find(|(n, _)| *n == name) else {
            return self.fail(pos, Code::UnknownType, unknown_type(name));
        };
        if args.len() != params {
            return self.fail(
                pos,
                Code::WrongArity,
                format!("{name} takes {params} argument(s), found {}", args.len()),
            );
        }
        // `I32` with `Decode.i32`, `FromJson.i32` and `ToJson.i32`, written as a number.
        let number = |ty: String| {
            let f = ty.to_lowercase();
            R::new(
                &ty,
                F::Name(format!("Decode.{f}")),
                F::Template("Num({x}.to_str())".into()),
                F::Name(format!("FromJson.{f}")),
                F::Name(format!("ToJson.{f}")),
            )
        };
        Ok(match name {
            "Bool" => R::prelude("Bool", "bool"),
            "String" => R::prelude("Str", "str"),
            "Bytes" => R::prelude("List(U8)", "bytes"),
            "Decimal" => R::prelude("Str", "decimal"),
            "Float32" => R::prelude("F32", "f32"),
            "Float64" => R::prelude("F64", "f64"),
            "Any" => R::prelude("Value", "any"),
            "Secret" => {
                self.uses_secret = true;
                let a = self.lower(&args[0], hint)?;
                let (de, en) = (self.value(&a.de), self.value(&a.en));
                let (from, to) = (self.json_value(&a.from_json), self.json_value(&a.to_json));
                let what = escape(&format!("Secret {}", args[0]));
                R::new(
                    &format!("Secret({})", a.ty),
                    F::Template(format!("Decode.secret({{x}}, \"{what}\", {de})")),
                    F::Template(format!("Encode.secret({{x}}, {en})")),
                    F::Template(format!("FromJson.secret({{x}}, \"{what}\", {from})")),
                    F::Template(format!("ToJson.secret({{x}}, \"{what}\", {to})")),
                )
            }
            "Int" => {
                self.uses_int = true;
                R::prelude("Int", "int")
            }
            "Int8" | "Int16" | "Int32" | "Int64" => number(format!("I{}", &name[3..])),
            "UInt8" | "UInt16" | "UInt32" | "UInt64" => number(format!("U{}", &name[4..])),
            "Array" | "Map" | "Maybe" => {
                let a = self.lower(&args[0], &format!("{hint}Item"))?;
                let (de, en) = (self.value(&a.de), self.value(&a.en));
                let (from, to) = (self.json_value(&a.from_json), self.json_value(&a.to_json));
                let (ty, helper) = match name {
                    "Array" => (format!("List({})", a.ty), "list"),
                    "Map" => (format!("List((Str, {}))", a.ty), "map"),
                    _ => (format!("[None, Some({})]", a.ty), "maybe"),
                };
                // A Maybe passes whether its inner JSON can be null; True forces the tagged form.
                let null = match (name, self.tagged_maybes.contains(&pos)) {
                    ("Maybe", true) => ", True".to_owned(),
                    ("Maybe", false) => format!(", {}", self.nullable_code(&a.nullable)),
                    _ => String::new(),
                };
                R::new(
                    &ty,
                    F::Template(format!("Decode.{helper}({{x}}, {de})")),
                    F::Template(format!("Encode.{helper}({{x}}, {en})")),
                    F::Template(format!("FromJson.{helper}({{x}}{null}, {from})")),
                    F::Template(format!("ToJson.{helper}({{x}}{null}, {to})")),
                )
            }
            "Result" => {
                let (e, a) =
                    (self.lower(&args[0], &format!("{hint}Err"))?, self.lower(&args[1], &format!("{hint}Ok"))?);
                let (ade, ede, aen, een) = (self.value(&a.de), self.value(&e.de), self.value(&a.en), self.value(&e.en));
                let (afrom, efrom) = (self.json_value(&a.from_json), self.json_value(&e.from_json));
                let (ato, eto) = (self.json_value(&a.to_json), self.json_value(&e.to_json));
                R::new(
                    &format!("Try({}, {})", a.ty, e.ty),
                    F::Template(format!("Decode.result({{x}}, {ade}, {ede})")),
                    F::Template(format!("Encode.result({{x}}, {aen}, {een})")),
                    F::Template(format!("FromJson.result({{x}}, {afrom}, {efrom})")),
                    F::Template(format!("ToJson.result({{x}}, {ato}, {eto})")),
                )
            }
            _ => {
                return self.fail(
                    pos,
                    Code::MisplacedStream,
                    format!("{name} is only allowed as the whole type of a definition"),
                );
            }
        })
    }

    /// A record or variant written inline: a structural type, with helper functions.
    fn inline(&mut self, ty: &Ty, hint: &str) -> Result<R> {
        let s = snake(hint);
        if !self.names.insert(hint.to_owned()) {
            return self.fail(
                ty.pos(),
                Code::DuplicateType,
                format!("the inline type here would be called {hint}, which is taken; give it a name"),
            );
        }
        // The helpers are functions of their own: note which `nullable_<p>` they use.
        let outer = std::mem::take(&mut self.nullables_used);
        let made = match ty {
            Ty::Record { closed, fields, .. } => self.record(hint, *closed, fields),
            Ty::Variant { closed: false, cases, .. } if cases.is_empty() => {
                let r = any_tag();
                Ok((r.ty.clone(), Bodies::of(&r)))
            }
            Ty::Variant { closed, cases, .. } => self.variant(hint, *closed, cases),
            _ => self.fail(ty.pos(), Code::SchemaSyntax, "expected a record or a variant here"),
        };
        let inner = std::mem::replace(&mut self.nullables_used, outer);
        let (rty, body) = made?;
        // In a generic type, the helpers take the decoders and encoders of the parameters they use.
        let used = params_in(ty);
        let passed: Vec<String> =
            self.params.iter().filter(|(h, _)| used.contains(h)).map(|(_, p)| p.clone()).collect();
        let p = Params::new(passed.iter().map(|p| (p.clone(), true, inner.contains(p))));
        let v = encoded_var(ty);
        let json = if self.json { Json::Unchecked } else { Json::None };
        self.helpers.push(functions("", "", &s, &rty, &body, &p, v, json));
        Ok(if passed.is_empty() {
            R::named(
                &rty,
                &format!("decode_{s}"),
                &format!("encode_{s}"),
                &format!("from_json_{s}"),
                &format!("to_json_{s}"),
            )
        } else {
            let (from, to) = self.json_args(&passed);
            R::new(
                &rty,
                F::Template(format!("decode_{s}({{x}}{})", p.de_args)),
                F::Template(format!("encode_{s}({{x}}{})", p.en_args)),
                F::Template(format!("from_json_{s}({{x}}{from})")),
                F::Template(format!("to_json_{s}({{x}}{to})")),
            )
        })
    }

    fn fields<'f>(&mut self, owner: &str, fields: &'f [Field]) -> Result<Vec<(String, &'static str, &'f Field, R)>> {
        let out = fields
            .iter()
            .map(|f| {
                let r = self.lower(&f.ty, &format!("{owner}{}", pascal(&f.key)))?;
                Ok((field_name(&f.key), if f.optional { "optional_field" } else { "field" }, f, r))
            })
            .collect::<Result<Vec<_>>>()?;
        // The first field whose Roc name an earlier one has (a set: linear in the fields).
        let mut seen = HashSet::new();
        match out.iter().enumerate().find(|(_, f)| !seen.insert(f.0.as_str())) {
            Some((_, (n, _, f, _))) => {
                self.fail(f.pos, Code::DuplicateField, format!("fields {} and another one are both {n} in Roc", f.key))
            }
            None => Ok(out),
        }
    }

    /// A record: its type, and the bodies of its functions.
    fn record(&mut self, owner: &str, closed: bool, fields: &[Field]) -> Result<(String, Bodies)> {
        let fs = self.fields(owner, fields)?;
        let parts = self.record_parts(&fs, "v");
        let check =
            |m: &str| if closed { format!("\t\t{m}.closed(fs, [{}])?\n", quoted(fields)) } else { String::new() };
        let fs_name = if fields.is_empty() && !closed { "_fs" } else { "fs" };
        let (decoded, read) = (&parts.decoded, &parts.read);
        let body = Bodies {
            de: format!("{{\n\t\t{fs_name} = Decode.strict_record(v)?\n{}\t\tOk({decoded})\n\t}}", check("Decode")),
            en: parts.encoded.clone(),
            from_json: format!(
                "{{\n\t\t{fs_name} = FromJson.object(j, \"{}\")?\n{}\t\tOk({read})\n\t}}",
                escape(owner),
                check("FromJson")
            ),
            to_json: format!("ToJson.object([{}])", parts.written),
        };
        Ok((parts.ty, body))
    }

    /// A record's type, its `{ … }` built from `fs` (a list of fields of a
    /// haus record or a JSON object), `Encode.record([…])` of the record
    /// `var`, and the fields of `ToJson.object([…])`.
    fn record_parts(&mut self, fs: &[(String, &'static str, &Field, R)], var: &str) -> RecordParts {
        let ty = fs
            .iter()
            .map(|(n, _, f, r)| {
                let ty = if f.optional { format!("[Missing, Present({})]", r.ty) } else { r.ty.clone() };
                format!("{n} : {ty}")
            })
            .collect::<Vec<_>>()
            .join(", ");
        let decoded = fs
            .iter()
            .map(|(n, how, f, r)| {
                let de = self.value(&r.de);
                format!("{n}: Decode.{how}(fs, \"{}\", {de})?", escape(&f.key))
            })
            .collect::<Vec<_>>()
            .join(", ");
        let read = fs
            .iter()
            .map(|(n, how, f, r)| {
                let from = self.json_value(&r.from_json);
                format!("{n}: FromJson.{how}(fs, \"{}\", {from})?", escape(&f.key))
            })
            .collect::<Vec<_>>()
            .join(", ");
        let mut write = |m: &str, f: &dyn Fn(&R) -> &F| {
            fs.iter()
                .map(|(n, _, field, r)| {
                    let key = escape(&field.key);
                    if field.optional {
                        let en = if m == "ToJson" { self.json_value(f(r)) } else { self.value(f(r)) };
                        format!("(\"{key}\", {m}.optional({var}.{n}, {en}))")
                    } else {
                        format!("(\"{key}\", Present({}))", f(r).apply(&format!("{var}.{n}")))
                    }
                })
                .collect::<Vec<_>>()
                .join(", ")
        };
        let encoded = write("Encode", &|r| &r.en);
        let written = write("ToJson", &|r| &r.to_json);
        RecordParts {
            ty: format!("{{ {ty} }}"),
            decoded: format!("{{ {decoded} }}"),
            encoded: format!("Encode.record([{encoded}])"),
            read: format!("{{ {read} }}"),
            written,
        }
    }

    /// Whether `ty`, a case's one argument, is a record type (see [`graph::record_case`]).
    fn record_case(&self, ty: &Ty) -> Option<Option<String>> {
        let imported = |name: &str| match self.imports.get(name)? {
            Source::Time => Some(graph::Shape::Other),
            Source::Module { template, .. } => Some(graph::shape(self.schema, *template)),
        };
        graph::record_case(ty, &self.defs, &imported)
    }

    /// A variant: its tag union, and the bodies of its functions.
    fn variant(&mut self, owner: &str, closed: bool, cases: &[Case]) -> Result<(String, Bodies)> {
        if let Some(case) = cases.iter().find(|c| !closed && c.tag == "Unknown") {
            return self.fail(
                case.pos,
                Code::DuplicateTag,
                "an open variant can't have a tag Unknown in Roc (unknown tags decode to Unknown); close it",
            );
        }
        // A closed variant whose tags have no payload is a string in JSON (spec §16.3).
        let names_only = closed && cases.iter().all(|c| c.payload.is_empty());
        let (mut tags, mut de, mut en, mut arity, mut from, mut to) = (vec![], vec![], vec![], vec![], vec![], vec![]);
        // Whether an arm of `from_json` reads the members `ms`.
        let mut reads_members = !closed;
        for case in cases {
            let tag = &case.tag;
            let hint = format!("{owner}{tag}");
            match case.payload.as_slice() {
                [] => {
                    tags.push(tag.clone());
                    de.push(format!("Tag(\"{tag}\", []) => Ok({tag})"));
                    en.push(format!("{tag} => Tag(\"{tag}\", [])"));
                    arity.push(format!("Tag(\"{tag}\", _) => Decode.arity(\"{tag}\", 0)"));
                    if names_only {
                        from.push(format!("\"{tag}\" => Ok({tag})"));
                        to.push(format!("{tag} => ToJson.tag_name(\"{tag}\")"));
                    } else {
                        reads_members = true;
                        from.push(format!(
                            "\"{tag}\" => match FromJson.args(ms, 0)? {{\n\t\t\t[] => Ok({tag})\n\t\t\t_ => FromJson.arity(\"{tag}\", 0)\n\t\t}}"
                        ));
                        to.push(format!("{tag} => ToJson.tagged(\"{tag}\", [])"));
                    }
                }
                [Ty::Record { closed: rc, fields, .. }] => {
                    let fs = self.fields(&hint, fields)?;
                    let parts = self.record_parts(&fs, "r");
                    let check =
                        if *rc { format!("Decode.closed(fs, [{}])?\n\t\t\t", quoted(fields)) } else { String::new() };
                    tags.push(format!("{tag}({})", parts.ty));
                    // `Tag {}`: no fields to read or write.
                    let (fs_arg, r) =
                        if fields.is_empty() { (if *rc { "fs" } else { "_fs" }, "_r") } else { ("fs", "r") };
                    let decoded = &parts.decoded;
                    de.push(format!(
                        "Tag(\"{tag}\", [p]) => Decode.payload(\"{tag}\", p, |{fs_arg}| {{\n\t\t\t{check}Ok({tag}({decoded}))\n\t\t}})"
                    ));
                    en.push(format!("{tag}({r}) => Tag(\"{tag}\", [{}])", parts.encoded));
                    arity.push(format!("Tag(\"{tag}\", _) => Decode.arity(\"{tag}\", 1)"));
                    // A field named `_tag` or `_args` has no schema-based form (spec §16.3).
                    if let Some(f) = fields.iter().find(|f| f.key == "_tag" || f.key == "_args") {
                        let name = &f.key;
                        from.push(format!("\"{tag}\" => FromJson.no_json_form(\"{tag}\", \"{name}\")"));
                        to.push(format!("{tag}(_) => ToJson.no_json_form(\"{tag}\", \"{name}\")"));
                    } else {
                        // The members are those of the tag's object: `"_tag"` is one of them.
                        let check = if *rc {
                            let known = ["\"_tag\"".to_owned()]
                                .into_iter()
                                .chain(fields.iter().map(|f| format!("\"{}\"", escape(&f.key))));
                            format!("\t\t\tFromJson.closed(ms, [{}])?\n", known.collect::<Vec<_>>().join(", "))
                        } else {
                            String::new()
                        };
                        reads_members |= *rc || !fields.is_empty();
                        let read = parts.read.replace("(fs, ", "(ms, ");
                        from.push(format!("\"{tag}\" => {{\n{check}\t\t\tOk({tag}({read}))\n\t\t}}"));
                        to.push(format!("{tag}({r}) => ToJson.tagged_object(\"{tag}\", [{}])", parts.written));
                    }
                }
                // A record case by name (spec §15): `Wrap Box` is `Wrap(Box)` in Roc, and
                // takes and writes what `Wrap { … }` does.
                [one] if self.record_case(one).is_some() => {
                    let reserved = self.record_case(one).flatten();
                    let r = self.lower(one, &hint)?;
                    tags.push(format!("{tag}({})", r.ty));
                    let f = self.value(&r.de);
                    de.push(format!("Tag(\"{tag}\", [p]) => Ok({tag}(Decode.record_arg(\"{tag}\", p, {f})?))"));
                    en.push(format!("{tag}(a0) => Tag(\"{tag}\", [{}])", r.en.apply("a0")));
                    arity.push(format!("Tag(\"{tag}\", _) => Decode.arity(\"{tag}\", 1)"));
                    match reserved {
                        // A field named `_tag` or `_args` has no schema-based form (spec §16.3).
                        Some(name) => {
                            from.push(format!("\"{tag}\" => FromJson.no_json_form(\"{tag}\", \"{name}\")"));
                            to.push(format!("{tag}(_) => ToJson.no_json_form(\"{tag}\", \"{name}\")"));
                        }
                        None => {
                            reads_members = true;
                            let f = self.json_value(&r.from_json);
                            from.push(format!("\"{tag}\" => Ok({tag}(FromJson.record_case(ms, {f})?))"));
                            to.push(format!("{tag}(a0) => ToJson.record_case(\"{tag}\", {})", r.to_json.apply("a0")));
                        }
                    }
                }
                items => {
                    let rs = items
                        .iter()
                        .enumerate()
                        .map(|(i, t)| {
                            self.lower(t, &if items.len() == 1 { hint.clone() } else { format!("{hint}{i}") })
                        })
                        .collect::<Result<Vec<_>>>()?;
                    let n = rs.len();
                    let vars: Vec<String> = (0..n).map(|i| format!("a{i}")).collect();
                    tags.push(format!("{tag}({})", rs.iter().map(|r| r.ty.clone()).collect::<Vec<_>>().join(", ")));
                    let values = rs
                        .iter()
                        .zip(&vars)
                        .enumerate()
                        .map(|(i, (r, var))| {
                            let f = self.value(&r.de);
                            format!("Decode.arg(\"{tag}\", {i}, {var}, {f})?")
                        })
                        .collect::<Vec<_>>()
                        .join(", ");
                    de.push(format!("Tag(\"{tag}\", [{}]) => Ok({tag}({values}))", vars.join(", ")));
                    let encoded = rs.iter().zip(&vars).map(|(r, var)| r.en.apply(var)).collect::<Vec<_>>().join(", ");
                    en.push(format!("{tag}({}) => Tag(\"{tag}\", [{encoded}])", vars.join(", ")));
                    arity.push(format!("Tag(\"{tag}\", _) => Decode.arity(\"{tag}\", {n})"));
                    let read = rs
                        .iter()
                        .zip(&vars)
                        .enumerate()
                        .map(|(i, (r, var))| {
                            let f = self.json_value(&r.from_json);
                            format!("FromJson.arg({n}, {i}, {var}, {f})?")
                        })
                        .collect::<Vec<_>>()
                        .join(", ");
                    reads_members = true;
                    from.push(format!(
                        "\"{tag}\" => match FromJson.args(ms, {n})? {{\n\t\t\t[{}] => Ok({tag}({read}))\n\t\t\t_ => FromJson.arity(\"{tag}\", {n})\n\t\t}}",
                        vars.join(", ")
                    ));
                    let written =
                        rs.iter().zip(&vars).map(|(r, var)| r.to_json.apply(var)).collect::<Vec<_>>().join(", ");
                    to.push(format!("{tag}({}) => ToJson.tagged(\"{tag}\", [{written}])", vars.join(", ")));
                }
            }
        }
        let names = cases.iter().map(|c| format!("\"{}\"", c.tag)).collect::<Vec<_>>().join(", ");
        if closed {
            de.extend(arity);
            de.push(format!("Tag(tag, _) => Decode.unknown_tag(tag, [{names}])"));
            // `tag` is bound already, by `FromJson.tag_name` or `FromJson.variant`.
            from.push(format!("_ => Decode.unknown_tag(tag, [{names}])"));
        } else {
            tags.push("Unknown(Str, List(Value))".into());
            de.extend(arity);
            de.push("Tag(tag, args) => Ok(Unknown(tag, args))".into());
            en.push("Unknown(tag, args) => Tag(tag, args)".into());
            from.push("_ => Ok(Unknown(tag, FromJson.unknown(tag, ms)?))".into());
            to.push("Unknown(tag, args) => ToJson.unknown(tag, args)".into());
        }
        de.push(format!("_ => Decode.expected(\"a variant ({owner})\", v)"));
        let arms = |arms: &[String], indent: &str| arms.iter().map(|a| format!("{indent}{a}\n")).collect::<String>();
        let from_json = if names_only {
            format!(
                "{{\n\t\ttag = FromJson.tag_name(j, \"{}\")?\n\t\tmatch tag {{\n{}\t\t}}\n\t}}",
                escape(owner),
                arms(&from, "\t\t\t")
            )
        } else {
            let ms = if reads_members { "ms" } else { "_ms" };
            format!(
                "{{\n\t\t(tag, {ms}) = FromJson.variant(j, \"{}\")?\n\t\tmatch tag {{\n{}\t\t}}\n\t}}",
                escape(owner),
                arms(&from, "\t\t\t")
            )
        };
        Ok((
            format!("[{}]", tags.join(", ")),
            Bodies {
                de: format!("match v {{\n{}\t}}", arms(&de, "\t\t")),
                en: format!("match v {{\n{}\t}}", arms(&en, "\t\t")),
                from_json,
                to_json: format!("match v {{\n{}\t}}", arms(&to, "\t\t")),
            },
        ))
    }
}

/// The bodies of a type's four functions: `decode_` over `v`, `encode_` over
/// `v`, `from_json_` over `j` and `to_json_` over `v`.
struct Bodies {
    de: String,
    en: String,
    from_json: String,
    to_json: String,
}

impl Bodies {
    /// The functions of `r`, applied.
    fn of(r: &R) -> Bodies {
        Bodies {
            de: r.de.apply("v"),
            en: r.en.apply("v"),
            from_json: r.from_json.apply("j"),
            to_json: r.to_json.apply("v"),
        }
    }
}

/// The parts of a record (see `Gen::record_parts`).
struct RecordParts {
    ty: String,
    decoded: String,
    encoded: String,
    read: String,
    written: String,
}

/// Which JSON functions a type or a helper gets.
#[derive(Clone, Copy)]
enum Json {
    None,
    /// `from_json_<s>` and `to_json_<s>`: a generic type's or a helper's.
    Unchecked,
    /// Also `read_json_<s>`, `from_json_<s>` without the depth check, which
    /// the readers of other types use: a type without parameters.
    Checked,
}

/// A type's (or a helper's) functions: `decode_<s>` and `encode_<s>`, and
/// with `json` `from_json_<s>` and `to_json_<s>`, after `doc` and `decl`.
///
/// The haus value read from schema-based JSON must nest at most 256 levels (spec
/// §16, "Limits"), and only the value as a whole can be measured: so the
/// `from_json_<s>` of a type without parameters encodes its result and
/// measures it (`FromJson.within_depth`), and calls `read_json_<s>`, which
/// doesn't, as the readers of other types do.
#[allow(clippy::too_many_arguments)]
fn functions(doc: &str, decl: &str, s: &str, head: &str, body: &Bodies, p: &Params, v: &str, json: Json) -> String {
    let decl = if decl.is_empty() { String::new() } else { format!("\t{decl}\n\n") };
    let Bodies { de, en, from_json, to_json } = body;
    let mut out = format!(
        "{doc}{decl}\tdecode_{s} : Value{} -> Try({head}, Decode.Error)\n\tdecode_{s} = |v{}| {de}\n\n\
         \tencode_{s} : {head}{} -> Value\n\tencode_{s} = |{v}{}| {en}\n",
        p.de_types, p.de_args, p.en_types, p.en_args
    );
    match json {
        Json::None => {}
        Json::Unchecked => {
            let _ = write!(
                out,
                "\n\tfrom_json_{s} : JsonValue{} -> Try({head}, Decode.Error)\n\tfrom_json_{s} = |j{}| {from_json}\n\n\
                 \tto_json_{s} : {head}{} -> Try(JsonValue, Encode.Error)\n\tto_json_{s} = |{v}{}| {to_json}\n",
                p.from_types, p.from_args, p.to_types, p.to_args
            );
        }
        Json::Checked => {
            let _ = write!(
                out,
                "\n\tfrom_json_{s} : JsonValue -> Try({head}, Decode.Error)\n\
                 \tfrom_json_{s} = |j| FromJson.within_depth(read_json_{s}(j), encode_{s})\n\n\
                 \tread_json_{s} : JsonValue -> Try({head}, Decode.Error)\n\tread_json_{s} = |j| {from_json}\n\n\
                 \tto_json_{s} : {head} -> Try(JsonValue, Encode.Error)\n\tto_json_{s} = |{v}| {to_json}\n",
            );
        }
    }
    out
}

/// The parameters of a generic definition or helper, as Roc code: the types
/// and names of the decoders and encoders that come after `v`, and of the
/// JSON readers and writers, each with whether the parameter's JSON can be
/// `null`, that come after `j`.
#[derive(Default)]
struct Params {
    de_types: String,
    de_args: String,
    en_types: String,
    en_args: String,
    from_types: String,
    from_args: String,
    to_types: String,
    to_args: String,
}

impl Params {
    /// Each parameter, whether it is used (`_decode_a` when not), and whether
    /// its `nullable_a` is (`_nullable_a` when not).
    fn new(params: impl Iterator<Item = (String, bool, bool)>) -> Params {
        params.fold(Params::default(), |mut p, (name, used, null_used)| {
            let unused = if used { "" } else { "_" };
            let null = if null_used { "" } else { "_" };
            let _ = write!(p.de_types, ", (Value -> Try({name}, Decode.Error))");
            let _ = write!(p.de_args, ", {unused}decode_{name}");
            let _ = write!(p.en_types, ", ({name} -> Value)");
            let _ = write!(p.en_args, ", {unused}encode_{name}");
            let _ = write!(p.from_types, ", (JsonValue -> Try({name}, Decode.Error)), Bool");
            let _ = write!(p.from_args, ", {unused}from_json_{name}, {null}nullable_{name}");
            let _ = write!(p.to_types, ", ({name} -> Try(JsonValue, Encode.Error)), Bool");
            let _ = write!(p.to_args, ", {unused}to_json_{name}, {null}nullable_{name}");
            p
        })
    }
}

/// The encoder's parameter: `_v` for `{}`, whose encoder doesn't read it.
fn encoded_var(ty: &Ty) -> &'static str {
    match ty {
        Ty::Record { fields, .. } if fields.is_empty() => "_v",
        _ => "v",
    }
}

/// The type parameters a type expression uses.
fn params_in(ty: &Ty) -> HashSet<String> {
    let mut out = HashSet::new();
    walk(ty, &mut |t| {
        if let Ty::Param { name, .. } = t {
            out.insert(name.clone());
        }
    });
    out
}

/// Every type expression in `ty`, `ty` included.
fn walk(ty: &Ty, f: &mut impl FnMut(&Ty)) {
    f(ty);
    match ty {
        Ty::Param { .. } => {}
        Ty::Name { args, .. } => args.iter().for_each(|a| walk(a, f)),
        Ty::Record { fields, .. } => fields.iter().for_each(|x| walk(&x.ty, f)),
        Ty::Variant { cases, .. } => cases.iter().flat_map(|c| &c.payload).for_each(|t| walk(t, f)),
    }
}

/// Whether a definition refers to itself, directly or through other definitions.
fn refers_to_itself(def: &TypeDef, defs: &HashMap<&str, &TypeDef>) -> bool {
    let names = |ty: &Ty| {
        let mut out = Vec::new();
        walk(ty, &mut |t| {
            if let Ty::Name { name, .. } = t
                && defs.contains_key(name.as_str())
            {
                out.push(name.clone());
            }
        });
        out
    };
    let (mut seen, mut todo) = (HashSet::new(), names(&def.ty));
    while let Some(name) = todo.pop() {
        if name == def.name {
            return true;
        }
        if seen.insert(name.clone()) {
            todo.extend(names(&defs[name.as_str()].ty));
        }
    }
    false
}

/// Doc lines for what is deprecated in a definition (spec §14), since Roc has
/// no marker for it: the type itself, and its fields and tags, inline ones too.
fn deprecations(def: &TypeDef) -> Vec<String> {
    fn line(what: &str, attrs: &[Attribute]) -> Option<String> {
        deprecation(attrs).map(|why| match why {
            Some(why) => format!("Deprecated{what}: {why}"),
            None => format!("Deprecated{what}."),
        })
    }
    fn ty(t: &Ty, path: &str, out: &mut Vec<String>) {
        match t {
            Ty::Name { args, .. } => args.iter().for_each(|a| ty(a, path, out)),
            Ty::Param { .. } => {}
            Ty::Record { fields, .. } => fields.iter().for_each(|f| {
                let at = format!("{path}{}", f.key);
                out.extend(line(&format!(" field `{at}`"), &f.attrs));
                ty(&f.ty, &format!("{at}."), out);
            }),
            Ty::Variant { cases, .. } => cases.iter().for_each(|c| {
                let at = format!("{path}{}", c.tag);
                out.extend(line(&format!(" tag `{at}`"), &c.attrs));
                c.payload.iter().for_each(|p| ty(p, &format!("{at}."), out));
            }),
        }
    }
    let mut out: Vec<String> = line("", &def.attrs).into_iter().collect();
    ty(&def.ty, "", &mut out);
    if !out.is_empty() {
        out.insert(0, String::new());
    }
    out
}

/// Roc's builtin types: a schema type with one of these names gets a `_` in Roc.
const BUILTIN_TYPES: &[&str] = &[
    "Str",
    "Bool",
    "List",
    "Dict",
    "Set",
    "Box",
    "Try",
    "Dec",
    "F32",
    "F64",
    "I8",
    "I16",
    "I32",
    "I64",
    "I128",
    "U8",
    "U16",
    "U32",
    "U64",
    "U128",
    "Stream",
    "Iter",
    "Hasher",
    "Utf8Problem",
    "Num",
];

/// Whether the JSON of a resolved type (of another module) can be `null`,
/// with its parameters' in `env`: as [`Gen::nullable_of`] decides for the
/// module that has the type, from its schema. A `Maybe` that reaches
/// itself through `Maybe`, `Secret` and names uses the tagged form.
fn nullable_resolved(
    schema: &Schema,
    ty: &Type,
    env: &HashMap<String, Nullable>,
    seen: &mut HashSet<InstanceId>,
) -> Nullable {
    match ty {
        Type::Param(p) => env.get(p).cloned().unwrap_or(Nullable::Never),
        Type::Secret(inner) => nullable_resolved(schema, inner, env, seen),
        Type::Maybe(inner) if !reaches(schema, inner, ty, &mut HashSet::new()) => {
            nullable_resolved(schema, inner, env, seen).not()
        }
        Type::Ref(id) if seen.insert(*id) => {
            let n = nullable_resolved(schema, &schema.instance(*id).body, env, seen);
            seen.remove(id);
            n
        }
        _ => Nullable::Never,
    }
}

/// Whether `ty` reaches the `Maybe` `target` through `Maybe`, `Secret` and names.
fn reaches(schema: &Schema, ty: &Type, target: &Type, seen: &mut HashSet<InstanceId>) -> bool {
    match ty {
        Type::Maybe(inner) => std::ptr::eq(ty, target) || reaches(schema, inner, target, seen),
        Type::Secret(inner) => reaches(schema, inner, target, seen),
        Type::Ref(id) => seen.insert(*id) && reaches(schema, &schema.instance(*id).body, target, seen),
        _ => false,
    }
}

/// `< >`: any tag.
fn any_tag() -> R {
    R::prelude("[Bare(Str), Other(Str, List(Value))]", "any_tag")
}

fn quoted(fields: &[Field]) -> String {
    fields.iter().map(|f| format!("\"{}\"", escape(&f.key))).collect::<Vec<_>>().join(", ")
}

fn escape(s: &str) -> String {
    s.replace('\\', "\\\\").replace('"', "\\\"").replace('$', "\\$")
}

/// `deliverTo` → `DeliverTo`, `money` → `Money`.
fn pascal(s: &str) -> String {
    s.split(|c: char| !c.is_ascii_alphanumeric())
        .filter(|w| !w.is_empty())
        .map(|w| w[..1].to_ascii_uppercase() + &w[1..])
        .collect()
}

/// `DeliverTo` → `deliver_to`.
fn snake(s: &str) -> String {
    s.chars().enumerate().fold(String::new(), |mut out, (i, c)| {
        match c {
            c if c.is_ascii_uppercase() => {
                if i > 0 && !out.ends_with('_') {
                    out.push('_');
                }
                out.push(c.to_ascii_lowercase());
            }
            c if c.is_ascii_alphanumeric() => out.push(c),
            _ if !out.ends_with('_') && !out.is_empty() => out.push('_'),
            _ => {}
        }
        out
    })
}

/// Words a Roc field can't be called.
const KEYWORDS: &[&str] = &[
    "if", "else", "match", "when", "is", "as", "import", "expect", "dbg", "crash", "return", "var", "for", "while",
    "and", "or", "has", "where", "module", "package", "app", "platform", "exposing", "break", "continue",
];

/// A field name in Roc: `deliverTo` → `deliver_to`, `type` → `type`, `if` → `if_`.
fn field_name(key: &str) -> String {
    match snake(key) {
        s if s.is_empty() => "field".into(),
        s if s.starts_with(|c: char| c.is_ascii_digit()) => format!("f{s}"),
        s if KEYWORDS.contains(&s.as_str()) => format!("{s}_"),
        s => s,
    }
}

#[cfg(test)]
mod tests {
    use super::generate;
    use crate::packages::Packages;

    fn roc(schema: &str) -> String {
        generate(schema, "M", "m", &[], &Packages::none()).unwrap_or_else(|e| panic!("{e}"))
    }

    fn error(schema: &str) -> String {
        generate(schema, "M", "m", &[], &Packages::none()).expect_err("an error").to_string()
    }

    #[test]
    fn floats_have_their_own_types() {
        let code = roc("type A = { x: Float32, y: Float64 }");
        assert!(code.contains("A : { x : F32, y : F64 }"), "{code}");
        assert!(code.contains("Decode.f32") && code.contains("Encode.f32"), "{code}");
    }

    #[test]
    fn names_of_roc_builtins_get_an_underscore() {
        let code = roc("type F64 = Float64\ntype Box = { w: Int }\ntype Value = Box");
        assert!(code.contains("F64_ : F64") && code.contains("Box_ : { w : Int }"), "{code}");
        assert!(code.contains("Value_ : Box_") && code.contains("decode_value = |v| decode_box(v)"), "{code}");
    }

    #[test]
    fn generic_types_take_decoders_and_encoders() {
        let code = roc("type Pair a = { first: a, second: a }\ntype Ints = Pair Int");
        assert!(
            code.contains("decode_pair : Value, (Value -> Try(a, Decode.Error)) -> Try(Pair(a), Decode.Error)"),
            "{code}"
        );
        assert!(code.contains("encode_pair : Pair(a), (a -> Value) -> Value"), "{code}");
        assert!(code.contains("decode_ints = |v| decode_pair(v, Decode.int)"), "{code}");
    }

    #[test]
    fn any_and_secret() {
        let code = roc("type A = { key: Secret String, pins: Array (Secret UInt16), extra: Any }");
        assert!(code.contains("import haus.Secret\n"), "{code}");
        assert!(code.contains("A : { key : Secret(Str), pins : List(Secret(U16)), extra : Value }"), "{code}");
        assert!(
            code.contains("Decode.field(fs, \"key\", |x4| Decode.secret(x4, \"Secret String\", Decode.str))?"),
            "{code}"
        );
        assert!(code.contains("Decode.field(fs, \"extra\", Decode.any)?"), "{code}");
        assert!(code.contains("(\"key\", Present(Encode.secret(v.key, Encode.str)))"), "{code}");
        assert!(!roc("type A = Int").contains("haus.Secret"));
    }

    #[test]
    fn deprecations_are_doc_comments() {
        let code = roc(
            "// A client.\n@deprecated(\"use Customer\")\ntype Client = { id: Int, @deprecated(\"use email\") mail?: String, \
             shape: < Circle | @deprecated Square > }",
        );
        assert!(
            code.contains(
                "\t## A client.\n\t##\n\t## haus type `m#Client`.\n\t##\n\t## Deprecated: use Customer\n\
                 \t## Deprecated field `mail`: use email\n\t## Deprecated tag `shape.Square`.\n"
            ),
            "{code}"
        );
    }

    #[test]
    fn every_line_of_a_deprecation_is_a_doc_comment() {
        let code = roc("type A = { @deprecated(\"use email\\nremoved in 2.0\") mail?: String }");
        assert!(code.contains("\t##\n\t## Deprecated field `mail`: use email\n\t## removed in 2.0\n\tA : {"), "{code}");
        let block = roc("@deprecated(\"\"\"\n  use B\n\n  removed in 2.0\n  \"\"\")\ntype A = Int");
        assert!(block.contains("\t## Deprecated: use B\n\t##\n\t## removed in 2.0\n\tA : Int"), "{block}");
    }

    #[test]
    fn prelude_types_take_their_number_of_arguments() {
        assert_eq!(error("type A = { key: Secret }"), "1:17: Secret takes 1 argument(s), found 0");
        assert_eq!(error("type A = Secret Int Int"), "1:10: Secret takes 1 argument(s), found 2");
        assert_eq!(error("type A = Result Int"), "1:10: Result takes 2 argument(s), found 1");
        assert_eq!(error("type A = Any Int"), "1:10: Any takes 0 argument(s), found 1");
        assert_eq!(
            error("type A = { s: Stream Int }"),
            "1:15: Stream is only allowed as the whole type of a definition"
        );
    }

    #[test]
    fn json_is_generated_on_request() {
        let json = |schema: &str| {
            super::generate_with_json(schema, "M", "m", &[], &Packages::none()).unwrap_or_else(|e| panic!("{e}"))
        };
        assert!(!roc("type A = Int32").contains("from_json"));
        let code = json("type A = { x: Int32, y?: Maybe Int64 }");
        assert!(code.contains("import haus.JsonValue\nimport haus.FromJson\nimport haus.ToJson\n"), "{code}");
        assert!(code.contains("from_json_a : JsonValue -> Try(A, Decode.Error)"), "{code}");
        assert!(code.contains("to_json_a : A -> Try(JsonValue, Encode.Error)"), "{code}");
        assert!(
            code.contains("FromJson.optional_field(fs, \"y\", |y1| FromJson.maybe(y1, False, FromJson.i64))?"),
            "{code}"
        );
        // Whether a Maybe's inner JSON can be null: from the definition, a
        // parameter's `nullable_a`, or True for one that reaches itself.
        let code = json("type O = Maybe Int32\ntype N = Maybe O\ntype H a = { held: Maybe a }\ntype L = Maybe L");
        assert!(code.contains("read_json_n = |j| FromJson.maybe(j, True, read_json_o)"), "{code}");
        assert!(
            code.contains(
                "from_json_h : JsonValue, (JsonValue -> Try(a, Decode.Error)), Bool -> Try(H(a), Decode.Error)"
            )
        );
        assert!(code.contains("FromJson.maybe(y1, nullable_a, from_json_a)"), "{code}");
        assert!(
            code.contains("L := [L([None, Some(L)])]") && code.contains("FromJson.maybe(j, True, read_json_l)"),
            "{code}"
        );
        // A closed variant of tags without payload is a string; others are tagged objects.
        let code = json(
            "type Level = closed < Debug | Info >\ntype S = < Circle { _tag: String } | Run { _args: Int32 } | Wrap Int32 >",
        );
        assert!(
            code.contains("tag = FromJson.tag_name(j, \"Level\")?")
                && code.contains("Debug => ToJson.tag_name(\"Debug\")")
        );
        assert!(code.contains("\"Circle\" => FromJson.no_json_form(\"Circle\", \"_tag\")"), "{code}");
        assert!(code.contains("Run(_) => ToJson.no_json_form(\"Run\", \"_args\")"), "{code}");
        assert!(code.contains("Wrap(a0) => ToJson.tagged(\"Wrap\", [ToJson.i32(a0)])"), "{code}");
        assert!(code.contains("_ => Ok(Unknown(tag, FromJson.unknown(tag, ms)?))"), "{code}");
    }

    #[test]
    fn json_readers_check_the_depth_of_the_whole_value() {
        let code = super::generate_with_json(
            "type L = Maybe L\ntype P a = { x: a }\ntype Q = P L",
            "M",
            "m",
            &[],
            &Packages::none(),
        )
        .unwrap_or_else(|e| panic!("{e}"));
        // A type without parameters measures what it read; the readers of
        // other types, and its own, call the one that doesn't.
        assert!(code.contains("from_json_l = |j| FromJson.within_depth(read_json_l(j), encode_l)"), "{code}");
        assert!(code.contains("read_json_l = |j| Ok(L(FromJson.maybe(j, True, read_json_l)?))"), "{code}");
        assert!(code.contains("read_json_q = |j| from_json_p(j, read_json_l, False)"), "{code}");
        // A generic type can't encode its parameters, so it doesn't.
        assert!(!code.contains("read_json_p") && !code.contains("FromJson.within_depth(from_json_p"), "{code}");
    }

    #[test]
    fn types_that_refer_to_themselves_are_nominal() {
        let code = roc("type Tree = { kids: Array Tree }\ntype List a = < Nil | Cons a (List a) >\ntype N = Array N");
        assert!(code.contains("Tree := { kids : List(Tree) }"), "{code}");
        assert!(code.contains("List_(a) := [Nil, Cons(a, List_(a)), Unknown(Str, List(Value))]"), "{code}");
        assert!(code.contains("N := [N(List(N))]"), "{code}");
    }
}
